import{_ as i,o as t,c as a,ag as e}from"./chunks/framework.DEqXEGcv.js";const k=JSON.parse('{"title":"Key Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"introduction/key-concepts.md","filePath":"introduction/key-concepts.md"}'),n={name:"introduction/key-concepts.md"};function l(o,s,r,h,d,p){return t(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="key-concepts" tabindex="-1">Key Concepts <a class="header-anchor" href="#key-concepts" aria-label="Permalink to &quot;Key Concepts&quot;">​</a></h1><h2 id="machine" tabindex="-1">Machine <a class="header-anchor" href="#machine" aria-label="Permalink to &quot;Machine&quot;">​</a></h2><p>A <strong>machine</strong> is a schema that defines the lifecycle of an entity. It declares data fields, states, transitions, guards, actions, and timeouts. Think of it as a blueprint.</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEFINE MACHINE SupportTicket (</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  DATA</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { ... }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  STATES { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">open</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, triaged, resolved, closed }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  INITIAL </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">STATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> open</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  TERMINAL STATES { closed }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  TRANSITIONS { ... }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Machines are registered in the <strong>catalog</strong> and can be evolved with <code>ALTER MACHINE</code>.</p><h2 id="instance" tabindex="-1">Instance <a class="header-anchor" href="#instance" aria-label="Permalink to &quot;Instance&quot;">​</a></h2><p>An <strong>instance</strong> is a single entity living within a machine&#39;s lifecycle. Each instance has:</p><ul><li>A <strong>ULID</strong> identifier (26-character, time-sortable)</li><li>A current <strong>state</strong></li><li><strong>Data</strong> fields matching the machine&#39;s schema</li><li>A <strong>version</strong> counter for optimistic concurrency</li><li>Timestamps: <code>created_at</code>, <code>updated_at</code>, <code>state_entered_at</code></li></ul><p>Instances are created with <code>SPAWN</code> and moved with <code>TRANSITION</code>.</p><h2 id="state" tabindex="-1">State <a class="header-anchor" href="#state" aria-label="Permalink to &quot;State&quot;">​</a></h2><p>A state represents a position in the lifecycle. Every machine has:</p><ul><li>An <strong>initial state</strong> — where new instances begin</li><li><strong>Terminal states</strong> — once reached, no further transitions are possible</li><li><strong>Regular states</strong> — intermediate positions in the lifecycle</li></ul><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">STATES { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">open</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, triaged, in_progress, resolved, closed }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">INITIAL </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">STATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> open</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TERMINAL STATES { closed }</span></span></code></pre></div><h2 id="transition" tabindex="-1">Transition <a class="header-anchor" href="#transition" aria-label="Permalink to &quot;Transition&quot;">​</a></h2><p>A <strong>transition</strong> moves an instance from one state to another. Transitions can include:</p><table tabindex="0"><thead><tr><th>Component</th><th>Purpose</th><th>Example</th></tr></thead><tbody><tr><td><strong>Guard</strong></td><td>Precondition that must be true</td><td><code>GUARD : assignee IS SET</code></td></tr><tr><td><strong>Mutate</strong></td><td>Data modification during transition</td><td><code>MUTATE : priority = critical</code></td></tr><tr><td><strong>Action</strong></td><td>Side effect after transition</td><td><code>ACTION : NOTIFY(assignee, &quot;assigned&quot;)</code></td></tr><tr><td><strong>Timeout</strong></td><td>Automatic transition after duration</td><td><code>TIMEOUT : 7d -&gt; closed</code></td></tr><tr><td><strong>Memo</strong></td><td>Human-readable note (per execution)</td><td><code>MEMO &quot;Resolved by customer&quot;</code></td></tr><tr><td><strong>Actor</strong></td><td>Identity performing the transition</td><td><code>AS { id: &quot;u1&quot;, role: &quot;admin&quot; }</code></td></tr></tbody></table><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">in_progress </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> resolved {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  GUARD   : resolution_note </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SET</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  GUARD   : ACTOR </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> assignee </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">OR</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ACTOR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">role</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ==</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;admin&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  TIMEOUT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> : 7d </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> closed</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ACTION</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  : NOTIFY(customer_id, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ticket.resolved&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="trail" tabindex="-1">Trail <a class="header-anchor" href="#trail" aria-label="Permalink to &quot;Trail&quot;">​</a></h2><p>Every instance maintains an immutable <strong>trail</strong> — a complete history of every state change. Each trail entry records:</p><ul><li><strong>Sequence number</strong> (0-indexed, starting with the spawn event)</li><li><strong>From state</strong> and <strong>to state</strong></li><li><strong>Actor</strong> who performed the transition</li><li><strong>Memo</strong> text (if provided)</li><li><strong>Timestamp</strong></li></ul><p>Query the trail with <code>TRAIL OF</code>:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TRAIL OF </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;01J5X7K2P3Q4R5S6T7U8V9W0XY&quot;</span></span></code></pre></div><h2 id="guard" tabindex="-1">Guard <a class="header-anchor" href="#guard" aria-label="Permalink to &quot;Guard&quot;">​</a></h2><p>A <strong>guard</strong> is a boolean expression that must evaluate to <code>true</code> for a transition to proceed. Guards can reference:</p><ul><li>Instance data fields: <code>assignee IS SET</code>, <code>priority == &quot;critical&quot;</code></li><li>The actor: <code>ACTOR.role == &quot;admin&quot;</code></li><li>Built-in functions: <code>elapsed_since(resolved) &lt; 30d</code></li><li>Child predicates: <code>ALL(items, STATE IS confirmed)</code></li></ul><p>Multiple guards on a transition are combined with AND — all must pass.</p><h2 id="actor" tabindex="-1">Actor <a class="header-anchor" href="#actor" aria-label="Permalink to &quot;Actor&quot;">​</a></h2><p>An <strong>actor</strong> is the identity performing a transition. Actors are maps with <code>id</code> and <code>role</code> fields, specified with the <code>AS</code> clause:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TRANSITION </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;01J5...&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> resolved</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { id: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;user-42&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">role</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;admin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>Guards reference the actor with the <code>ACTOR</code> keyword: <code>ACTOR.role == &quot;admin&quot;</code>.</p><h2 id="composition" tabindex="-1">Composition <a class="header-anchor" href="#composition" aria-label="Permalink to &quot;Composition&quot;">​</a></h2><p>Machines can have <strong>children</strong> — instances of other machines that belong to a parent. This enables hierarchical patterns like Order → LineItem, Pipeline → Stage → Job.</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CHILDREN {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  items    : LIST(LineItem) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> MIN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  shipment : OPTIONAL(Shipment)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Children support predicates (<code>ALL()</code>, <code>ANY()</code>), cascade transitions, and <code>SIGNAL PARENT TO</code> for upward communication.</p>`,34)])])}const g=i(n,[["render",l]]);export{k as __pageData,g as default};
